function ref(name) {
  try { return $(name).item.json; } catch (e) { return $(name).first().json; }
}
const ctx = ref('Code - Apply Mapping & Merge');
const profileA = ref('Code - Generate Transform Rules').profileA;
const profileB = ref('Code - Generate Transform Rules').profileB;

const mappedSources = new Set((ctx.ruleList || []).map(r => r.source));
const mappedTargets = new Set((ctx.ruleList || []).map(r => r.target));

const unmatchedA = Object.keys(profileA.fields || {}).filter(f => !mappedSources.has(f));
const unmatchedB = Object.keys(profileB.fields || {}).filter(f => !mappedTargets.has(f));

const report = {
  requestId: ctx.requestId,
  generatedAt: new Date().toISOString(),
  aiOk: ctx.aiOk,
  stats: ctx.stats,
  mappings: (ctx.ruleList || []).map(r => ({
    from: r.source,
    to: r.target,
    confidence: r.confidence,
    transform: r.transform
  })),
  lowConfidence: (ctx.ruleList || []).filter(r => r.confidence < 0.7),
  unmatchedFromA: unmatchedA,
  unmatchedFromB: unmatchedB,
  summary: `Mapped ${ctx.stats.fieldsMapped} fields using strategy "${ctx.stats.mergeStrategy}". ` +
           `Merged ${ctx.stats.rowsA} + ${ctx.stats.rowsB} → ${ctx.stats.rowsMerged} rows.`
};

return [{
  json: {
    requestId: ctx.requestId,
    merged: ctx.merged,
    mappedA: ctx.mappedA,
    report,
    stats: ctx.stats
  }
}];

function ref(name) {
  try { return $(name).item.json; } catch (e) { return $(name).first().json; }
}
const ctx = ref('Code - Generate Transform Rules');
const rules = ctx.rules || {};
const datasetA = ctx.datasetA || [];
const datasetB = ctx.datasetB || [];
const { mergeStrategy, joinKey, keepUnmapped } = ctx.config;

function applyRules(row) {
  const out = {};
  for (const [target, rule] of Object.entries(rules)) {
    let val = row[rule.source];

    if (val === undefined || val === null) {
      val = rule.defaultValue !== null ? rule.defaultValue : null;
    } else {
      switch (rule.transform) {
        case 'string':   val = String(val); break;
        case 'number':   val = Number(val); break;
        case 'boolean':  val = Boolean(val); break;
        case 'lowercase': if (typeof val === 'string') val = val.toLowerCase(); break;
        case 'uppercase': if (typeof val === 'string') val = val.toUpperCase(); break;
        case 'split':    if (typeof val === 'string') val = val.split(/[,;|]/).map(s => s.trim()); break;
        case 'concatenate':
          // expression can be "first_name + ' ' + last_name"
          if (rule.expression) {
            try {
              // very limited safe eval – only allow field names + string literals + +
              const expr = rule.expression.replace(/([a-zA-Z_][a-zA-Z0-9_]*)/g, (m) => {
                return row[m] !== undefined ? JSON.stringify(row[m]) : '""';
              });
              val = eval(expr);
            } catch (e) { val = null; }
          }
          break;
        case 'dateFormat':
          // expects ISO or epoch; outputs YYYY-MM-DD
          try {
            const d = new Date(val);
            if (!isNaN(d)) val = d.toISOString().slice(0, 10);
          } catch (e) {}
          break;
        // 'rename' and unknown → keep as-is
      }
    }
    out[target] = val;
  }

  if (keepUnmapped) {
    for (const [k, v] of Object.entries(row)) {
      if (!(k in out) && !Object.values(rules).some(r => r.source === k)) {
        out['_src_' + k] = v;
      }
    }
  }
  return out;
}

const mappedA = datasetA.map(row => applyRules(row));

// ---------- Merge strategies ----------
let merged = [];
if (mergeStrategy === 'concat') {
  merged = [...mappedA, ...datasetB];
} else {
  // index B by joinKey
  const indexB = new Map();
  for (const row of datasetB) {
    const key = row[joinKey];
    if (key !== undefined && key !== null) {
      if (!indexB.has(key)) indexB.set(key, []);
      indexB.get(key).push(row);
    }
  }

  const usedB = new Set();

  for (const a of mappedA) {
    const key = a[joinKey];
    const matches = key !== undefined && key !== null ? (indexB.get(key) || []) : [];
    if (matches.length) {
      for (const b of matches) {
        merged.push({ ...b, ...a });          // A wins on collision
        usedB.add(b);
      }
    } else if (mergeStrategy === 'left' || mergeStrategy === 'outer') {
      merged.push({ ...a });
    }
  }

  if (mergeStrategy === 'right' || mergeStrategy === 'outer') {
    for (const b of datasetB) {
      if (!usedB.has(b)) merged.push({ ...b });
    }
  }
  // inner is already handled by only pushing matches
}

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    mappings: ctx.mappings,
    ruleList: ctx.ruleList,
    mappedA,
    datasetB,
    merged,
    stats: {
      rowsA: datasetA.length,
      rowsB: datasetB.length,
      rowsMerged: merged.length,
      fieldsMapped: Object.keys(rules).length,
      mergeStrategy,
      joinKey
    },
    aiOk: ctx.aiOk
  }
}];

function ref(name) {
