}
const ctx = ref('Code - Parse AI Mappings');

const rules = {};
for (const m of ctx.mappings || []) {
  rules[m.target] = {
    source: m.source,
    confidence: m.confidence,
    transform: m.transform,
    defaultValue: m.defaultValue,
    expression: m.expression
  };
}

const ruleList = Object.entries(rules).map(([target, r]) => ({
  target,
  source: r.source,
  confidence: r.confidence,
  transform: r.transform
}));

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    datasetA: ctx.datasetA,
    datasetB: ctx.datasetB,
    profileA: ctx.profileA,
    profileB: ctx.profileB,
    targetSchema: ctx.targetSchema,
    mappings: ctx.mappings,
    rules,
    ruleList,
    aiOk: ctx.aiOk
  }
}];

function ref(name) {
  try { return $(name).item.json; } catch (e) { return $(name).first().json; }
}
const ctx = ref('Code - Validate & Profile');
const res = $input.first().json || {};
const statusCode = Number(res.statusCode) || 0;

let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}
if (!body || typeof body !== 'object') body = {};

// Expected shape from a real LLM:
// { mappings: [ { source, target, confidence, transform, defaultValue? }, ... ] }
let mappings = Array.isArray(body.mappings) ? body.mappings : [];

// ---------- Strong heuristic fallback (works with httpbin mock) ----------
if (mappings.length === 0) {
  const fieldsA = Object.keys(ctx.profileA.fields || {});
  const fieldsB = Object.keys(ctx.profileB.fields || {});
  const targetList = Array.isArray(ctx.targetSchema) && ctx.targetSchema.length
    ? ctx.targetSchema
    : fieldsB;
  const usedTargets = new Set();
  const hints = ctx.hints || {};

  // 1. Honour explicit hints first
  for (const [src, tgt] of Object.entries(hints)) {
    if (fieldsA.includes(src) && targetList.includes(tgt)) {
      mappings.push({ source: src, target: tgt, confidence: 0.98, transform: 'rename' });
      usedTargets.add(tgt);
    }
  }

  // 2. Fuzzy match remaining fields
  for (const a of fieldsA) {
    if (mappings.some(m => m.source === a)) continue;
    const aNorm = a.toLowerCase().replace(/[_\s-]/g, '');
    let best = null;
    let bestScore = 0;
    for (const b of targetList) {
      if (usedTargets.has(b)) continue;
      const bNorm = b.toLowerCase().replace(/[_\s-]/g, '');
      let score = 0;
      if (aNorm === bNorm) score = 0.95;
      else if (aNorm.includes(bNorm) || bNorm.includes(aNorm)) score = 0.78;
      else if (aNorm.slice(0, 5) === bNorm.slice(0, 5)) score = 0.62;
      if (score > bestScore) { bestScore = score; best = b; }
    }
    if (best && bestScore >= ctx.config.minConfidence) {
      mappings.push({ source: a, target: best, confidence: bestScore, transform: 'rename' });
      usedTargets.add(best);
    }
  }
}

// Normalise + filter
mappings = mappings
  .map(m => ({
    source: String(m.source || '').trim(),
    target: String(m.target || '').trim(),
    confidence: Math.min(1, Math.max(0, Number(m.confidence) || 0.5)),
    transform: (m.transform || 'rename').toLowerCase(),
    defaultValue: m.defaultValue !== undefined ? m.defaultValue : null,
    expression: m.expression || null          // optional safe expression
  }))
  .filter(m => m.source && m.target && m.confidence >= ctx.config.minConfidence);

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    datasetA: ctx.datasetA,
    datasetB: ctx.datasetB,
    profileA: ctx.profileA,
    profileB: ctx.profileB,
    targetSchema: ctx.targetSchema,
    mappings,
    aiStatus: statusCode,
    aiOk: statusCode >= 200 && statusCode < 300
  }
}];

