function ref(name) {
  try { return $(name).item.json; } catch (e) { return $(name).first().json; }
}

const DEFAULTS = {
  aiMappingUrl: 'https://httpbin.org/post',
  aiTimeoutMs: 30000,
  maxSampleRows: 5,
  minConfidence: 0.55,
  mergeStrategy: 'concat',          // concat | left | right | inner | outer
  joinKey: null,
  keepUnmapped: false,
  allowSimulation: true
};

const hook = ref('Webhook - Submit Datasets');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const datasetA = Array.isArray(body.datasetA) ? body.datasetA : [];
const datasetB = Array.isArray(body.datasetB) ? body.datasetB : [];
const hints = body.hints && typeof body.hints === 'object' ? body.hints : {};
const targetSchema = Array.isArray(body.targetSchema) ? body.targetSchema : null;

if (datasetA.length === 0) errors.push('datasetA must be a non-empty array of objects');
if (datasetB.length === 0) errors.push('datasetB must be a non-empty array of objects');

const mergeStrategy = (body.mergeStrategy || DEFAULTS.mergeStrategy).toLowerCase();
if (!['concat','left','right','inner','outer'].includes(mergeStrategy)) {
  errors.push('mergeStrategy must be one of: concat, left, right, inner, outer');
}

const joinKey = body.joinKey || DEFAULTS.joinKey;
if (mergeStrategy !== 'concat' && !joinKey) {
  errors.push('joinKey is required when mergeStrategy is not "concat"');
}

function profile(rows, maxSamples) {
  if (!rows.length) return { fields: {}, samples: [] };
  const fields = {};
  for (const row of rows.slice(0, 80)) {
    for (const [k, v] of Object.entries(row || {})) {
      if (!fields[k]) fields[k] = { types: {}, nulls: 0, examples: [] };
      const t = v === null || v === undefined ? 'null'
                : Array.isArray(v) ? 'array'
                : typeof v;
      fields[k].types[t] = (fields[k].types[t] || 0) + 1;
      if (v === null || v === undefined) fields[k].nulls += 1;
      else if (fields[k].examples.length < 3) fields[k].examples.push(v);
    }
  }
  return { fields, samples: rows.slice(0, maxSamples) };
}

const profileA = profile(datasetA, DEFAULTS.maxSampleRows);
const profileB = profile(datasetB, DEFAULTS.maxSampleRows);

const config = {
  ...DEFAULTS,
  minConfidence: Number(body.minConfidence) || DEFAULTS.minConfidence,
  mergeStrategy,
  joinKey,
  keepUnmapped: body.keepUnmapped === true,
  aiTimeoutMs: Number(body.aiTimeoutMs) || DEFAULTS.aiTimeoutMs
};

let aiUrl = config.aiMappingUrl;
const sim = Number(body.simulateStatus);
if (config.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  aiUrl = 'https://httpbin.org/status/' + sim;
}

const valid = errors.length === 0;

return [{
  json: {
    valid,
    errors,
    config,
    datasetA,
    datasetB,
    hints,
    targetSchema,
    profileA,
    profileB,
    aiUrl,
    requestId: body.requestId || ('map-' + Date.now())
  }
}];
